/** 数值工具 **/
type OperationEnum = "+" | "-" | "*" | "/";

/**
* @name 计算数值
 * @param {number} [type="+"] 运算：+、-、*、/
 * @param {number} [num1=0] 数值
 * @param {number} [num2=0] 数值
 */
function calcNum(type: OperationEnum = "+", num1 = 0, num2 = 0): number {
	const n1 = parseFloat(num1.toString());
	const n2 = parseFloat(num2.toString());
	if (isNaN(n1) || isNaN(n2)) return NaN;
	const dot1 = (n1.toString().split(".")[1] || "").length;
	const dot2 = (n2.toString().split(".")[1] || "").length;
	const maxDotLen = Math.max(dot1, dot2, 0);
	const pow = 10 ** maxDotLen;
	const x = Math.round(n1 * pow);
	const y = Math.round(n2 * pow);
	if (type === "+") {
		return (x + y) / pow;
	} else if (type === "-") {
		return (x - y) / pow;
	} else if (type === "*") {
		return x * y / (pow * pow);
	} else {
		return x / y;
	}
}

/**
* @name N个计算数值
 * @param {number} [type="+"] 运算：+、-、*、/
 * @param {array} [nums=[]] 数值集合
 */
function calcNumPlus(type: OperationEnum = "+", ...nums: number[]): number {
	const config = { "*": 1, "+": 0, "/": 1, "-": 0 };
	let res = config[type] || 0;
	for (let i = 0; i < nums.length; i++) {
		if (i === 0 && (type === "-" || type === "/")) {
			res = nums[i];
			continue;
		}
		res = calcNum(type, res, nums[i]);
	}
	return res;
}

/**
 * @name 补零数值
 * @param {number} [num=0] 数值
 * @param {number} [len=0] 补位
 */
function fillNum(num = 0, len = 0): string {
	return num.toString().padStart(len, "0");
}

/**
 * @name 取整数值
 * @param {number} [dec=2] 小数个数
 * @param {number} [num=0] 数值
 * @param {string} [type="round"] 数学函数：ceil向上取整、floor向下取整、round四舍五入
 */
function fixedNum({
	dec = 2,
	num,
	type = "round"
}: {
	dec?: number
	num: number
	type?: "ceil" | "floor" | "round"
}): number {
	const pow = 10 ** dec;
	return Math[type](num * pow) / pow;
}

/**
 * @name 格式字节
 * @param {number} [byte=0] 字节
 */
function formatByte(byte = 0): string {
	if (byte === 0) return "0 B";
	const unit = 1024;
	const sizes = ["B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"];
	const i = Math.floor(Math.log(byte) / Math.log(unit));
	return `${(byte / unit ** i).toPrecision(3)} ${sizes[i]}`;
}

/**
 * @name 范围随机数
 * @param {number} [min=0] 最小数
 * @param {number} [max=10] 最大数
 */
function randomNum(min = 0, max = 10): number {
	return Math.floor(Math.random() * (max - min + 1) + min);
}

/**
 * @name N个范围随机数
 * @param {number} [min=0] 最小数
 * @param {number} [max=10] 最大数
 * @param {number} [count=1] 个数
 */
function randomNumPlus(min = 0, max = 10, count = 1): number[] {
	const maxCount = Math.max(0, Math.min(count, max - min + 1));
	if (maxCount === 0) return [];
	const randoms = new Set<number>();
	while (randoms.size < maxCount) {
		randoms.add(randomNum(min, max));
	}
	return Array.from(randoms);
}

/**
 * @name 精确数值(四舍五入和百分比)
 * @param {number} [dec=2] 小数个数
 * @param {number} [num=0] 数值
 * @param {boolean} [per=false] 百分比
 */
function roundNum({
	dec = 2,
	num,
	per = false
}: {
	dec?: number
	num: number
	per?: boolean
}): string | number {
	const pow = 10 ** dec;
	return per
		? `${Math.round(num * pow * 100) / pow}%`
		: Math.round(num * pow) / pow;
}

/**
 * @name 千分数值
 * @param {number} [num=0] 数值
 */
function thousandNum(num: number): string {
	return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

export {
	calcNum,
	calcNumPlus,
	fillNum,
	fixedNum,
	formatByte,
	randomNum,
	randomNumPlus,
	roundNum,
	thousandNum
};