/** URL工具 **/
import { isBrowser, isEmptyObject } from "./boolean";

type DataType = Record<string | number, string | number | boolean | null | undefined>;

type SearchType = Record<string, string>;

/**
 * @name URL参数反序列化
 * @param {string} [search=""] URL参数
 */
function parseUrlSearch(search = ""): SearchType {
	const finalSearch = !search && isBrowser() ? location.search : search;
	if (!finalSearch) return {};
	const query = finalSearch.replace(/(^\?)|(&$)/g, "");
	const searchParams = new URLSearchParams(query);
	const result: SearchType = {};
	searchParams.forEach((val, key) => {
		result[key] = val;
	});
	return result;
}

/**
 * @name URL参数序列化
 * @param {object} [search={}] 参数集合
 * @param {boolean} [clear=false] 清除假值(undefined、null、""、NaN)
 */
function stringifyUrlSearch(search: DataType = {}, clear = false): string {
	if (isEmptyObject(search)) return "";
	const params = new URLSearchParams();
	for (const [key, val] of Object.entries(search)) {
		if (clear && [undefined, null, "", NaN, false].includes(val)) {
			continue;
		}
		if (val !== undefined && val !== null) {
			params.append(key, String(val));
		} else if (!clear) {
			params.append(key, "");
		}
	}
	const result = params.toString();
	return result ? `?${result}` : "";
}

export {
	parseUrlSearch,
	stringifyUrlSearch
};