/** 对象工具 **/
type KeyEnum = string | number | symbol;

type ObjType<T> = Record<KeyEnum, T | "">;

/**
 * @name 检查对象有效键名
 * @param {object} [obj={}] 对象
 * @param {string|number|symbol} [key=""] 键名
 */
function checkObjValidKey<T>(obj: ObjType<T> = {}, key: KeyEnum = ""): key is keyof typeof obj {
	return key in obj;
}

/**
 * @name 过滤对象键名
 * @param {object} [obj={}] 对象
 * @param {array} [keys=[]] 键名集合
 */
function filterObjKey<T>(obj: ObjType<T> = {}, keys: KeyEnum[] = []): ObjType<T> {
	const newObj: ObjType<T> = {};
	for (const key of keys) {
		if (Object.hasOwn(obj, key)) {
			newObj[key] = obj[key];
		}
	}
	return newObj;
}

/**
 * @name 删除对象空键
 * @param {object} [obj={}] 对象
 * @param {boolean} [clear=false] 清除假值
 */
function removeObjEmptyKey<T>(obj: ObjType<T> = {}, clear = false): ObjType<T> {
	const newObj: ObjType<T> = {};
	for (const key in obj) {
		if (Object.hasOwn(obj, key)) {
			const val = obj[key];
			const isEmpty = clear ? !val : val === "";
			if (!isEmpty) {
				newObj[key] = val;
			}
		}
	}
	return newObj;
}

export {
	checkObjValidKey,
	filterObjKey,
	removeObjEmptyKey
};