/** DOM 工具 **/
import { asyncTo } from "../common";

/**
 * @name 自适应
 * @param {number} [size=750] 设计图宽度
 */
function autoResponse(size = 750): void {
	const elem = document.documentElement;
	const width = elem.clientWidth;
	const height = elem.clientHeight;
	const isLandscape = width > height;
	const actualWidth = isLandscape ? height : width;
	elem.style.fontSize = actualWidth >= 600 ? "80px" : `${actualWidth / size * 100}px`;
}

/**
 * @name B64转文件
 * @param {string} [base64=""] Base64
 * @param {string} [filename="unknow"] 文件名称
 */
function base64ToFile(base64 = "", name = "unknow"): File {
	const arr = base64.split(",");
	const type = /:(.*?);/.exec(arr[0])?.[1] ?? "jpg";
	const ext = type.split("/")[1];
	const bstr = atob(arr[1]);
	let len = bstr.length;
	const u8arr = new Uint8Array(len);
	while (len--) {
		u8arr[len] = bstr.charCodeAt(len);
	}
	return new File([u8arr], `${name}.${ext}`, { type });
}

/**
 * @name 复制粘贴
 * @param {string} [text=""] 文本
 * @param {element} [elem=document.body] 节点
 */
async function copyPaste(text = "", elem: HTMLElement = document.body): Promise<boolean> {
	const range = document.createRange();
	const selection = getSelection();
	if (selection) {
		range.selectNodeContents(elem);
		selection.removeAllRanges();
		selection.addRange(range);
		const [err] = await asyncTo(navigator.clipboard.writeText(text));
		selection.removeAllRanges();
		return !err;
	} else {
		return false;
	}
}

/**
 * @name 下载文件
 * @param {string} [url=""] 地址
 * @param {string} [name="unknow"] 文件名称
 */
function downloadFile(url = "", name = "unknow"): void {
	const event = new Event("MouseEvents");
	const target = document.createElement("a");
	target.setAttribute("href", url);
	target.setAttribute("download", name);
	target.click();
	target.dispatchEvent(event);
}

/**
 * @name 下载文本
 * @param {string} [text=""] 文本
 * @param {string} [name="unknow"] 文件名称
 */
function downloadText(text = "", name = "unknow"): void {
	const event = new Event("MouseEvents");
	const target = document.createElement("a");
	target.setAttribute("href", `data:text/plain;charset=utf-8,${encodeURIComponent(text)}`);
	target.setAttribute("download", name);
	target.click();
	target.dispatchEvent(event);
}

/**
 * @name 过滤XSS
 * @param {string} [html=""] HTML
 */
function filterXss(html = ""): string {
	const elem = document.createElement("div");
	elem.innerText = html;
	const result = elem.innerHTML;
	return result;
}

/**
 * @name 高亮文本
 * @param {string} [text=""] 文本
 * @param {string} [keyword=""] 关键字
 */
function highlightText(text = "", keyword = ""): string {
	const separator = text.match(keyword)?.[0];
	return separator ? text.split(separator).join(`<span>${separator}</span>`) : text;
}

/**
 * @name 图像转B64
 * @param {string} [url=""] 地址
 * @param {string} [type="jpg"] 类型：jpg、jpeg、png
 */
async function imgToBase64(url = "", type: "jpg" | "jpeg" | "png" = "jpg"): Promise<string> {
	const promise = new Promise<string>(resolve => {
		const img = new Image();
		const finalType = type === "jpg" ? "jpeg" : type;
		img.setAttribute("src", url);
		img.setAttribute("crossOrigin", "");
		img.addEventListener("load", () => {
			const canvas = document.createElement("canvas");
			canvas.setAttribute("width", `${img.width}px`);
			canvas.setAttribute("height", `${img.height}px`);
			canvas.getContext("2d")?.drawImage(img, 0, 0);
			const dataURL = canvas.toDataURL(`image/${finalType}`);
			resolve(dataURL);
		});
		img.addEventListener("error", () => resolve(""));
	});
	const [err, res] = await asyncTo(promise);
	return !err && res ? res : "";
}

/**
 * @name JSONP
 * @param {string} [name="jsonp"] 全局变量
 * @param {function} [onCall] 回调函数
 * @param {string} [url=""] 地址
 */
interface JsonpType<T> {
	name: string
	url: string
	onCall?: (data: T) => void
}

async function jsonp<T>({
	name,
	onCall,
	url
}: JsonpType<T>): Promise<boolean> {
	const promise = new Promise<boolean>(resolve => {
		const script = document.createElement("script");
		script.setAttribute("src", url);
		script.setAttribute("async", "true");
		script.addEventListener("load", () => resolve(true));
		script.addEventListener("error", () => resolve(false));
		// eslint-disable-next-line @typescript-eslint/no-explicit-any
		(window as any)[name] = (data: T) => onCall?.(data);
		document.body.appendChild(script);
	});
	const [err, res] = await asyncTo(promise);
	return !err && res;
}

/**
 * @name 加载脚本
 * @param {string} [url=""] 地址
 * @param {string} [pst="body"] 插入位置：head、body
 */
async function loadScript(url = "", pst: "body" | "head" = "body"): Promise<boolean> {
	const promise = new Promise<boolean>(resolve => {
		const scripts = document.getElementsByTagName("script");
		if ([...scripts].some(v => v.src === url || v.src.includes(url))) {
			resolve(false);
		}
		const script = document.createElement("script");
		script.setAttribute("src", url);
		script.addEventListener("load", () => resolve(true));
		script.addEventListener("error", () => resolve(false));
		pst === "head" && document.head.appendChild(script);
		pst === "body" && document.body.appendChild(script);
	});
	const [err, res] = await asyncTo(promise);
	return !err && res;
}

/**
 * @name 禁止事件
 * @param {array} [events=[]] 事件：contextmenu、copy、selectstart
 */
function prohibitEvent(events: Array<"contextmenu" | "copy" | "selectstart"> = []): void {
	const evs = [...new Set(events)].sort();
	evs.forEach(v => document.addEventListener(v, e => e.preventDefault()));
}

export {
	autoResponse,
	base64ToFile,
	copyPaste,
	downloadFile,
	downloadText,
	filterXss,
	highlightText,
	imgToBase64,
	jsonp,
	loadScript,
	prohibitEvent
};