/** 函数工具 **/
import { isFormData, stringifyUrlSearch } from "../common";

type DataType = Record<string | number, string | number | boolean | null | undefined>;

/**
 * @name 异步请求
 * @param {object} [data={}] 参数集合
 * @param {object} [headers={}] 请求头
 * @param {string} [method="get"] 方法：get、post
 * @param {number} [timeout] 超时
 * @param {string} [url=""] 地址
 * @param {boolean} [useCookie={}] 携带 cookie
 * @param {boolean} [useJson={}] 参数 JSON 化
 */
interface ResponseType<T> {
	code: number
	data: T | null
	flag: boolean
	msg: string
}

async function aios<T, P extends object = Record<string, unknown>>({
	data = {},
	headers = {},
	method = "get",
	timeout = 10000,
	url,
	useCookie = true,
	useJson = false
}: {
	data?: DataType | FormData
	headers?: object
	method?: "get" | "post"
	timeout?: number
	url: string
	useCookie?: boolean
	useJson?: boolean
}): Promise<[Error | null, ResponseType<T> & P | null]> {
	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(), timeout);
	const isGet = method === "get";
	let finalUrl = url;
	let body: BodyInit | undefined = undefined;
	if (isGet) {
		const params = stringifyUrlSearch(data as DataType, true).replace(/^\?/g, "");
		finalUrl = params ? `${url}${params ? `?${params}` : ""}` : url;
	} else if (isFormData(data)) {
		body = data as FormData;
	} else if (useJson) {
		body = JSON.stringify(data);
	} else {
		body = stringifyUrlSearch(data as DataType, true).replace(/^\?/g, "");
	}
	const promise = fetch(finalUrl, {
		body: isGet ? undefined : body,
		credentials: useCookie ? "include" : "omit",
		headers: headers as HeadersInit,
		method,
		signal: controller.signal
	}).then(async res => {
		clearTimeout(timer);
		const json = await res.json() as ResponseType<T> & P;
		return [null, { data: json, status: res.status }] as [null, { data: ResponseType<T> & P; status: number }];
	})
		.catch(err => {
			clearTimeout(timer);
			return [err as Error, null] as [Error, null];
		});
	const [err, res] = await promise;
	return [err, !err && res.status === 200 ? res.data : null];
}

/**
 * @name 异步请求
 * @param {object} [data={}] 参数集合
 * @param {function} [error=null] 失败回调函数
 * @param {function} [success=null] 成功回调函数
 * @param {string} [type="get"] 类型：get、post
 * @param {string} [url=""] 地址
 */
function ajax({
	data = {},
	error,
	success,
	type = "get",
	url
}: {
	data?: DataType
	type?: "get" | "post"
	url: string
	error?: (status: number) => void
	success?: (res: string) => void
}): void {
	const xhr = new XMLHttpRequest();
	const method = type.toUpperCase();
	const params = stringifyUrlSearch(data);
	if (method === "GET") {
		xhr.open("GET", `${url}${params}`, true);
		xhr.send();
	} else if (method === "POST") {
		xhr.open("POST", url, true);
		xhr.setRequestHeader("Content-type", "application/x-www-form-urlencoded");
		xhr.send(params);
	}
	xhr.onreadystatechange = function() {
		if (xhr.readyState === 4) {
			if (xhr.status === 200) {
				success?.(xhr.responseText);
			} else {
				error?.(xhr.status);
			}
		}
	};
}

export {
	aios,
	ajax
};