/** Storage 工具 **/

/**
 * @name 清空LocalStorage
 */
function clearLStorage(): void {
	localStorage.clear();
}

/**
 * @name 清空SessionStorage
 */
function clearSStorage(): void {
	sessionStorage.clear();
}

/**
 * @name 读取LocalStorage
 * @param {string} [key=""] 键
 */
function getLStorage<T>(key = ""): T | null {
	const item = localStorage.getItem(key);
	return item ? JSON.parse(item) : null;
}

/**
 * @name 读取SessionStorage
 * @param {string} [key=""] 键
 */
function getSStorage<T>(key = ""): T | null {
	const item = sessionStorage.getItem(key);
	return item ? JSON.parse(item) : null;
}

/**
 * @name 删除LocalStorage
 * @param {string} [key=""] 键
 */
function removeLStorage(key = ""): void {
	localStorage.removeItem(key);
}

/**
 * @name 删除SessionStorage
 * @param {string} [key=""] 键
 */
function removeSStorage(key = ""): void {
	sessionStorage.removeItem(key);
}

/**
 * @name 设置LocalStorage
 * @param {string} [key=""] 键
 * @param {any} [val=""] 值
 */
function setLStorage<T>(key = "", val: T): void {
	localStorage.setItem(key, JSON.stringify(val));
}

/**
 * @name 设置SessionStorage
 * @param {string} [key=""] 键
 * @param {any} [val=""] 值
 */
function setSStorage<T>(key = "", val: T): void {
	sessionStorage.setItem(key, JSON.stringify(val));
}

export {
	clearLStorage,
	clearSStorage,
	getLStorage,
	getSStorage,
	removeLStorage,
	removeSStorage,
	setLStorage,
	setSStorage
};