/** 数组工具 **/
import { isNull, isUndefined } from "./boolean";

type KeyEnum = string | number;

/**
 * @name 分割数组
 * @param {array} [arr=[]] 数组
 * @param {number} [size=1] 尺寸
 */
function chunkArr<T>(arr: T[] = [], size = 1): T[][] {
	if (!arr.length || size < 1) return [];
	const chunked: T[][] = [];
	for (let i = 0; i < arr.length; i += size) {
		chunked.push(arr.slice(i, i + size));
	}
	return chunked;
}

/**
 * @name 分组数组
 * @param {array} [arr=[]] 数组
 * @param {string|number} [key=""] 属性
 */
function groupArr<T extends Record<K, KeyEnum>, K extends keyof T>(arr: T[] = [], key: K): Record<KeyEnum, T[]> {
	const grouped: Record<KeyEnum, T[]> = {};
	for (const v of arr) {
		const k = v[key];
		if (!isUndefined(k) && !isNull(k)) {
			grouped[k] ??= [];
			grouped[k].push(v);
		}
	}
	return grouped;
}

/**
 * @name 统计数组成员个数
 * @param {array} [arr=[]] 数组
 */
type MemCountType = Record<KeyEnum, number>;

function statArrMemCount(arr: KeyEnum[] = []): MemCountType {
	const counts: MemCountType = {};
	for (const v of arr) {
		counts[v] = (counts[v] || 0) + 1;
	}
	return counts;
}

/**
 * @name 统计数组成员所含关键字
 * @param {array} [arr=[]] 数组
 * @param {array} [keywords=[]] 关键字集合
 */
function statArrMemKeyword(arr: string[] = [], keywords: string[] = []): string[] {
	return keywords.filter(v => arr.some(w => w.includes(v)));
}

/**
 * @name 记录数组成员位置
 * @param {array} [arr=[]] 数组
 * @param {string|number|boolean} [val] 值
 */
type MemValueEnum = string | number | boolean | null | undefined;

function statArrMemPosition(arr: MemValueEnum[] = [], val: MemValueEnum): number[] {
	const positions: number[] = [];
	for (let i = 0; i < arr.length; i++) {
		if (arr[i] === val) {
			positions.push(i);
		}
	}
	return positions;
}

export {
	chunkArr,
	groupArr,
	statArrMemCount,
	statArrMemKeyword,
	statArrMemPosition
};