/** Cookie 工具 **/
type CookieType = Record<string, string>;

/**
 * @name 读取Cookie
 */
function getCookie(): CookieType {
	const cookies = document.cookie;
	if (!cookies) return {};
	const result: CookieType = {};
	for (const v of cookies.split("; ")) {
		const [key, val] = v.split("=");
		if (key) result[key] = val;
	}
	return result;
}

/**
 * @name 删除Cookie
 * @param {string} [key=""] 键
 */
function removeCookie(key = ""): void {
	setCookie(key, "", -1);
}

/**
 * @name 设置Cookie
 * @param {string} [key=""] 键
 * @param {string} [val=""] 值
 * @param {number} [day=1] 过期时间(日)
 */
function setCookie(key = "", val = "", day = 1): void {
	const date = new Date();
	date.setDate(date.getDate() + day);
	document.cookie = `${key}=${val};expires=${date.toString()}`;
}

export {
	getCookie,
	removeCookie,
	setCookie
};